/**
 * Cours de langues vivantes : chaque unité associe un axe culturel du programme, un point de grammaire
 * et le lexique du thème. Les points de grammaire sont rédigés une fois et partagés entre unités.
 */

interface Point { title: string; rules: string[]; examples: string[]; pitfalls: string[]; remember: string[] }

const G: Record<string, Point> = {
  /* ——— Anglais ——— */
  "en:be-have": { title: "be et have got", rules: ["be : I am, you are, he/she/it is, we/you/they are ; formes contractées I'm, he's, they're.", "have got (possession) : I have got, she has got ; question : Have you got… ? ; négation : I haven't got.", "Question avec be : on inverse le sujet et be (Is she French?)."], examples: ["She is twelve and she has got two brothers.", "Are you from London? — No, I'm not."], pitfalls: ["Dire « I have twelve » pour l'âge : on dit « I am twelve ».", "Oublier has à la 3e personne : she has got."], remember: ["L'âge se dit avec be.", "has got à la 3e personne du singulier."] },
  "en:present-simple": { title: "le présent simple et les adverbes de fréquence", rules: ["Présent simple : habitudes, vérités générales ; -s à la 3e personne du singulier (she plays).", "Questions et négations avec do/does : Do you play? She doesn't play.", "Adverbes de fréquence (always, usually, often, sometimes, never) : avant le verbe, mais après be."], examples: ["He usually gets up at seven.", "She is never late."], pitfalls: ["Oublier le -s : he play.", "Garder le -s après does : Does she plays?"], remember: ["he/she/it : -s.", "Adverbe de fréquence avant le verbe, après be."] },
  "en:there-is": { title: "there is / there are", rules: ["there is + nom singulier ; there are + nom pluriel : il y a.", "Questions : Is there… ? Are there… ? ; négation : There isn't / there aren't.", "some dans les phrases affirmatives, any dans les questions et les négations."], examples: ["There is a castle near the town.", "Are there any shops in your street?"], pitfalls: ["Dire « it has » pour « il y a ».", "Employer there is avec un pluriel."], remember: ["there is + singulier, there are + pluriel.", "some / any."] },
  "en:preterit-regular": { title: "le prétérit de be et des verbes réguliers", rules: ["be : I/he/she/it was ; you/we/they were.", "Verbes réguliers : base verbale + -ed (played, visited, stopped).", "Questions et négations avec did + base verbale : Did you play? I didn't play."], examples: ["Once upon a time, there was a king.", "The children played in the forest yesterday."], pitfalls: ["Garder -ed après did : Did you played?", "Confondre was et were."], remember: ["was / were.", "did + base verbale (sans -ed)."] },
  "en:like-ing": { title: "like, love, hate + verbe en -ing", rules: ["Pour exprimer ses goûts : like, love, enjoy, hate + verbe en -ing.", "Orthographe : dance → dancing, swim → swimming (doublement), play → playing.", "I don't like / I can't stand pour exprimer le rejet."], examples: ["I love drawing but I hate singing.", "She enjoys reading comics."], pitfalls: ["Utiliser l'infinitif sans to après enjoy : enjoy read.", "Oublier le doublement : swiming."], remember: ["like / love / hate + -ing.", "swim → swimming."] },
  "en:comparatives": { title: "les comparatifs et les superlatifs", rules: ["Adjectifs courts : -er than / the -est (tall → taller than → the tallest).", "Adjectifs longs : more … than / the most … (more interesting).", "Irréguliers : good → better → the best ; bad → worse → the worst.", "Égalité : as … as."], examples: ["My sister is taller than me.", "This is the most beautiful city in Scotland."], pitfalls: ["Cumuler les deux formes : more taller.", "Oublier than."], remember: ["court : -er ; long : more.", "good → better → best."] },
  "en:present-continuous": { title: "le présent simple et le présent en be + -ing", rules: ["Présent simple : habitudes (every day, usually).", "be + -ing : action en cours au moment où l'on parle (now, at the moment).", "Certains verbes d'état (like, know, want) ne se mettent pas en be + -ing."], examples: ["I usually walk to school, but today I'm taking the bus.", "Look! It's snowing."], pitfalls: ["Employer be + -ing pour une habitude.", "Dire « I am knowing »."], remember: ["Habitude : présent simple ; maintenant : be + -ing.", "Verbes d'état : présent simple."] },
  "en:modals": { title: "can, must, have to", rules: ["can : capacité ou permission (I can swim ; Can I go out?).", "must : obligation ressentie par celui qui parle ; mustn't : interdiction.", "have to : obligation extérieure ; don't have to : absence d'obligation.", "Les modaux ne prennent pas de -s et sont suivis de la base verbale."], examples: ["You mustn't use your phone in class.", "We don't have to wear a uniform."], pitfalls: ["Confondre mustn't (interdit) et don't have to (pas obligé).", "Mettre to après must : must to go."], remember: ["mustn't = interdiction ; don't have to = pas besoin.", "Modal + base verbale."] },
  "en:preterit-irregular": { title: "le prétérit des verbes irréguliers", rules: ["Les verbes irréguliers ont une forme propre au prétérit : go → went, see → saw, take → took, buy → bought, eat → ate, write → wrote, come → came, have → had.", "Questions et négations : did + base verbale (Did you go? I didn't see).", "Le prétérit exprime une action passée et terminée, souvent datée (yesterday, last summer, in 2020, two years ago)."], examples: ["Last summer we went to Ireland and saw the cliffs.", "Did they take the train? — No, they didn't."], pitfalls: ["Employer la forme irrégulière après did : did you went?", "Ajouter -ed à un verbe irrégulier : goed."], remember: ["go → went, see → saw, take → took.", "did + base verbale."] },
  "en:future": { title: "le futur avec will et be going to", rules: ["will + base verbale : prédiction, décision prise sur le moment, promesse.", "be going to + base verbale : intention, ou prévision fondée sur un indice présent.", "Le présent en be + -ing exprime aussi un futur proche organisé."], examples: ["I think it will rain tomorrow.", "Look at those clouds: it's going to rain!"], pitfalls: ["Mettre to après will.", "Oublier be dans be going to : I going to."], remember: ["will : prédiction, décision immédiate.", "be going to : intention, indice présent."] },
  "en:passive": { title: "la voix passive", rules: ["be (au temps voulu) + participe passé : The castle was built in 1200.", "Le complément d'agent est introduit par by.", "On choisit le passif pour mettre en valeur ce qui subit l'action ou quand l'agent est inconnu."], examples: ["English is spoken all over the world.", "The painting was stolen last night."], pitfalls: ["Oublier be : The castle built in 1200.", "Mettre le mauvais temps à be."], remember: ["be + participe passé.", "by + agent."] },
  "en:causative": { title: "le passif et le causatif", rules: ["Passif : be + participe passé (The monument was restored).", "Causatif : have / get + objet + participe passé = faire faire (I had my bike repaired).", "make + objet + base verbale = obliger quelqu'un à faire."], examples: ["The memorial was unveiled in 1922.", "They had the statue cleaned."], pitfalls: ["Confondre « I repaired my bike » et « I had my bike repaired ».", "Mettre to après make : make him to do."], remember: ["have something done = faire faire.", "make somebody do."] },
  "en:should": { title: "must, have to, should", rules: ["must / have to : obligation (intérieure / extérieure).", "should + base verbale : conseil, recommandation.", "shouldn't : déconseiller."], examples: ["You should revise every day.", "Students have to wear a badge."], pitfalls: ["Utiliser must pour un simple conseil.", "Ajouter -s : he shoulds."], remember: ["should = conseil.", "must / have to = obligation."] },
  "en:present-perfect": { title: "le present perfect et le prétérit", rules: ["Present perfect : have/has + participe passé ; lien entre le passé et le présent (expérience, résultat, durée qui continue).", "Marqueurs : ever, never, already, yet, just, since + point de départ, for + durée.", "Prétérit : passé coupé du présent, avec un moment précis (yesterday, in 2019, ago)."], examples: ["Have you ever been to New York? — Yes, I went there in 2022.", "She has lived in Dublin for three years."], pitfalls: ["Utiliser le present perfect avec une date passée : I have visited London in 2020.", "Confondre since et for."], remember: ["Date précise : prétérit.", "since + point de départ ; for + durée."] },
  "en:will-would": { title: "will, would et le discours indirect", rules: ["will : avenir probable ; would : avenir imaginé, conditionnel (I would like to…).", "Discours indirect : He said (that) he would come ; on décale les temps (will → would, present → past) et les repères (tomorrow → the next day)."], examples: ["One day, robots will help doctors.", "She said she would travel to India."], pitfalls: ["Garder will après said.", "Oublier de changer les pronoms."], remember: ["will → would au discours indirect.", "Décaler les temps et les repères."] },
  "en:used-to": { title: "used to et would", rules: ["used to + base verbale : habitude ou état passés, révolus.", "would + base verbale : habitude passée répétée (pas pour un état).", "Négation : didn't use to ; question : Did you use to… ?"], examples: ["My grandparents used to live on a farm.", "Every Sunday, we would visit our cousins."], pitfalls: ["Confondre used to (habitude passée) et be used to + -ing (être habitué à).", "Employer would avec un verbe d'état (would live)."], remember: ["used to : c'était comme ça avant.", "would : habitude répétée."] },
  "en:past-perfect": { title: "le prétérit et le past perfect", rules: ["Past perfect : had + participe passé ; action antérieure à une autre action passée.", "Il sert à remonter dans le passé dans un récit au prétérit."], examples: ["When we arrived, the film had already started.", "She realised she had lost her keys."], pitfalls: ["Utiliser le prétérit pour l'action la plus ancienne quand l'ordre n'est pas clair.", "Confondre had (avoir) et had + participe passé."], remember: ["had + participe passé = antériorité dans le passé.", "Deux actions passées : la plus ancienne au past perfect."] },
  "en:modals-advanced": { title: "les modaux d'obligation et de possibilité", rules: ["Obligation : must, have to ; conseil : should, ought to.", "Possibilité : can, could, may, might (du plus sûr au moins sûr).", "Capacité passée : could ; permission polie : may / could."], examples: ["We must reduce our emissions.", "Electric cars might become cheaper."], pitfalls: ["Mettre to après un modal (sauf ought to, have to).", "Confondre can (capacité) et may (éventualité)."], remember: ["must > should : obligation > conseil.", "may / might : éventualité."] },
  "en:reported": { title: "le discours rapporté", rules: ["Verbes introducteurs : say (that), tell somebody (that), ask (if/whether), explain, claim.", "Décalage des temps : present → past, present perfect → past perfect, will → would.", "Changements de repères : here → there, now → then, yesterday → the day before."], examples: ["\"I am tired,\" she said. → She said (that) she was tired.", "He asked me if I had seen the film."], pitfalls: ["Utiliser say avec un complément de personne : he said me.", "Garder l'ordre interrogatif : He asked where was I."], remember: ["tell + personne ; say sans personne.", "Question indirecte : ordre sujet-verbe."] },
  "en:concession": { title: "la concession : although, however", rules: ["although / even though + proposition : bien que (sans subjonctif en anglais).", "however en début de phrase, suivi d'une virgule : cependant.", "despite / in spite of + nom ou verbe en -ing."], examples: ["Although it was raining, they went out.", "Despite the cold, they swam."], pitfalls: ["Employer despite avec une proposition complète : despite it was raining.", "Oublier la virgule après however."], remember: ["although + sujet + verbe.", "despite + nom / -ing."] },
  "en:conditional": { title: "le conditionnel", rules: ["would + base verbale : I would like, she would help.", "Hypothèse sur le présent : if + prétérit, would + base verbale (If I had time, I would paint).", "Avec be, on emploie were à toutes les personnes dans la langue soignée : If I were you…"], examples: ["If artists were free, they would criticise the government.", "I would rather stay at home."], pitfalls: ["Mettre would dans la proposition en if.", "Écrire « If I would have »."], remember: ["if + prétérit → would.", "If I were you, I would…"] },
  "en:hypothesis": { title: "l'expression de l'hypothèse", rules: ["Réel : if + présent → will (If it rains, we will stay).", "Irréel du présent : if + prétérit → would (If I knew, I would tell you).", "Irréel du passé : if + past perfect → would have + participe passé (If I had known, I would have come).", "unless = if … not."], examples: ["If scientists find a cure, millions will benefit.", "If they had tested it, they would have seen the risk."], pitfalls: ["Employer will après if.", "Mélanger les trois structures."], remember: ["if + présent / prétérit / past perfect.", "unless = si … ne … pas."] },
  "en:purpose": { title: "le but et la conséquence", rules: ["But : to / in order to + base verbale ; so that + sujet + can/could/will.", "Conséquence : so, therefore, as a result, consequently ; so + adjectif + that, such + nom + that."], examples: ["They planted trees in order to fight erosion.", "The river was so polluted that the fish died."], pitfalls: ["Employer for + base verbale pour le but (for to save).", "Confondre so (si) et so that (pour que)."], remember: ["to / in order to = pour.", "so … that = si … que."] },
  "en:nuance": { title: "nuancer : may, might, could", rules: ["Degrés de probabilité : will (certain) > should (probable) > may > might / could (possible).", "Adverbes : probably, perhaps, maybe, certainly.", "Passé : may/might have + participe passé (il se peut que … ait)."], examples: ["Public spaces might become more digital.", "She may have forgotten the meeting."], pitfalls: ["Croire que might est le passé de may dans ce sens.", "Mettre to après might."], remember: ["may / might / could : possibilité.", "may have + participe passé : hypothèse sur le passé."] },
  "en:emphasis": { title: "les structures emphatiques", rules: ["Phrase clivée : It is … that / who … (It was the author who changed the ending).", "What + proposition + is … (What matters is the truth).", "do / does / did emphatique : I do like this book."], examples: ["It is in this novel that the hero discovers the truth.", "What surprised me was the end."], pitfalls: ["Oublier that dans la phrase clivée.", "Mettre -s au verbe après does : does likes."], remember: ["It is … that / who.", "What … is …"] },
  "en:wish": { title: "l'hypothèse : if only, I wish", rules: ["I wish / If only + prétérit : regret ou souhait sur le présent (I wish I had more time).", "I wish / If only + past perfect : regret sur le passé (If only I had known).", "I wish + would : souhaiter qu'une autre personne change (I wish you would listen)."], examples: ["I wish people spent less time online.", "If only I hadn't posted that photo!"], pitfalls: ["Employer le présent après I wish.", "Confondre regret présent et passé."], remember: ["wish + prétérit : présent.", "wish + past perfect : passé."] },
  "en:speech-complex": { title: "le discours rapporté complexe", rules: ["Verbes introducteurs variés : admit, deny, suggest, warn, claim, insist.", "suggest + -ing ou suggest that + sujet + base verbale ; warn somebody not to + base verbale.", "Ordres : tell / ask somebody to + base verbale."], examples: ["The journalist claimed that the figures had been changed.", "She warned us not to share the link."], pitfalls: ["suggest somebody to do (incorrect).", "Oublier le décalage des temps."], remember: ["Choisir un verbe introducteur précis.", "tell somebody (not) to do."] },

  /* ——— Espagnol ——— */
  "es:gustar": { title: "gustar et l'expression des goûts", rules: ["me gusta + nom singulier ou infinitif ; me gustan + nom pluriel.", "Pronoms : me, te, le, nos, os, les ; pour insister : a mí me gusta, a ellos les gusta.", "encantar (adorer) et interesar se construisent de la même façon."], examples: ["Me gusta el fútbol pero me encantan los videojuegos.", "A mi hermana le gusta leer."], pitfalls: ["Dire « yo gusto » pour « j'aime ».", "Accorder gustar avec la personne au lieu de la chose aimée."], remember: ["gusta + singulier ; gustan + pluriel.", "La chose aimée est le sujet."] },
  "es:presente": { title: "le présent des verbes irréguliers", rules: ["Diphtongue : e → ie (querer → quiero), o → ue (poder → puedo), sauf avec nosotros et vosotros.", "Affaiblissement e → i : pedir → pido.", "Irréguliers à la 1re personne : tengo, hago, pongo, salgo, conozco ; ser : soy ; ir : voy."], examples: ["Quiero aprender alemán.", "¿Puedes venir mañana? — Sí, puedo."], pitfalls: ["Diphtonguer avec nosotros : *queremos* est correct, pas « quieremos ».", "Dire « teno » au lieu de « tengo »."], remember: ["e → ie, o → ue (sauf nosotros, vosotros).", "tengo, hago, salgo, pongo."] },
  "es:obligacion": { title: "l'obligation : tener que, hay que", rules: ["tener que + infinitif : obligation personnelle (Tengo que estudiar).", "hay que + infinitif : obligation impersonnelle, générale (Hay que respetar las normas).", "deber + infinitif : devoir moral."], examples: ["En mi colegio, hay que llevar uniforme.", "Mañana tienes que levantarte temprano."], pitfalls: ["Conjuguer hay : hay que reste invariable.", "Oublier que : tengo estudiar."], remember: ["tener que : moi, toi…", "hay que : tout le monde."] },
  "es:pronominales": { title: "les verbes pronominaux", rules: ["Le pronom s'accorde avec le sujet : me levanto, te duchas, se viste, nos acostamos, os laváis, se despiertan.", "À l'infinitif, le pronom se colle au verbe : levantarse, voy a levantarme.", "Beaucoup décrivent la routine quotidienne."], examples: ["Me levanto a las siete y me ducho.", "¿A qué hora te acuestas?"], pitfalls: ["Oublier le pronom : yo levanto.", "Mettre se avec toutes les personnes."], remember: ["me, te, se, nos, os, se.", "levantarse → me levanto."] },
  "es:ser-estar": { title: "ser et estar", rules: ["ser : identité, caractéristique durable, origine, profession, matière, heure (Es alto ; Es de México ; Son las tres).", "estar : état passager, localisation, résultat (Está cansado ; Madrid está en España).", "estar + gérondif : action en cours (Estoy leyendo)."], examples: ["Mi madre es médica y hoy está muy cansada.", "La playa está cerca del hotel."], pitfalls: ["Employer ser pour la localisation.", "Dire « soy cansado »."], remember: ["ser : ce qu'on est ; estar : comment / où on est.", "estar + -ando / -iendo."] },
  "es:imperfecto": { title: "l'imparfait", rules: ["-ar : -aba, -abas, -aba, -ábamos, -abais, -aban ; -er/-ir : -ía, -ías, -ía, -íamos, -íais, -ían.", "Trois irréguliers : ser (era), ir (iba), ver (veía).", "Emplois : description, habitudes passées, comparaison avec aujourd'hui (antes…, ahora…)."], examples: ["Antes, mis abuelos vivían en el campo.", "Cuando era pequeño, iba al colegio a pie."], pitfalls: ["Oublier l'accent sur -ía.", "Utiliser l'imparfait pour une action ponctuelle datée."], remember: ["-aba / -ía.", "era, iba, veía."] },
  "es:indefinido": { title: "le passé simple (pretérito indefinido)", rules: ["Réguliers : hablé, hablaste, habló, hablamos, hablasteis, hablaron ; comí, comiste, comió, comimos, comisteis, comieron.", "Irréguliers fréquents : fui (ser et ir), tuve, estuve, hice, pude, puse, dije, vine.", "Action passée, ponctuelle et terminée ; marqueurs : ayer, el año pasado, en 2010, hace dos años."], examples: ["El verano pasado fuimos a Perú.", "Ayer hizo mucho calor."], pitfalls: ["Oublier l'accent : hablo (présent) ≠ habló (passé).", "Confondre fui (ser) et fui (ir) : le contexte décide."], remember: ["-é, -aste, -ó, -amos, -asteis, -aron.", "ayer, el año pasado → indefinido."] },
  "es:futuro": { title: "le futur", rules: ["Infinitif + -é, -ás, -á, -emos, -éis, -án : hablaré, comerás, vivirá.", "Irréguliers : tendré, haré, diré, podré, saldré, vendré, pondré, querré, sabré.", "ir a + infinitif exprime un futur proche."], examples: ["El año que viene estudiaré en Madrid.", "Mañana tendremos un examen."], pitfalls: ["Oublier l'accent : hablare.", "Dire « teneré » au lieu de « tendré »."], remember: ["Infinitif + terminaisons.", "tendré, haré, diré."] },
  "es:ir-a": { title: "ir a + infinitif", rules: ["Futur proche : ir (conjugué au présent) + a + infinitif.", "voy, vas, va, vamos, vais, van + a + infinitif."], examples: ["Este verano voy a visitar Sevilla.", "¿Qué vais a hacer el sábado?"], pitfalls: ["Oublier a : voy visitar.", "Conjuguer l'infinitif."], remember: ["voy a + infinitif.", "Le a est obligatoire."] },
  "es:adjetivos": { title: "les adjectifs et leurs accords", rules: ["L'adjectif s'accorde en genre et en nombre : alto, alta, altos, altas.", "Adjectifs en -e ou en consonne : même forme au masculin et au féminin (inteligente, joven).", "Apocope devant un nom masculin singulier : buen chico, mal día ; gran devant tout nom singulier."], examples: ["Mi hermana es alta y simpática.", "Es un buen amigo."], pitfalls: ["Accorder un adjectif en -e : inteligenta.", "Oublier l'apocope : un bueno día."], remember: ["-o / -a / -os / -as.", "buen, mal, gran."] },
  "es:comparar": { title: "la comparaison", rules: ["Supériorité : más + adjectif + que ; infériorité : menos + adjectif + que ; égalité : tan + adjectif + como.", "Irréguliers : mejor, peor, mayor (plus âgé), menor (plus jeune).", "Avec un nom : tanto/tanta/tantos/tantas + nom + como."], examples: ["Las fiestas de Valencia son más ruidosas que las de mi pueblo.", "Mi hermano es mayor que yo."], pitfalls: ["Dire « más bueno » pour « mejor ».", "Employer que après tan."], remember: ["más / menos … que ; tan … como.", "mejor, peor, mayor, menor."] },
  "es:perfecto": { title: "le passé composé et le passé simple", rules: ["Pretérito perfecto : haber au présent (he, has, ha, hemos, habéis, han) + participe (hablado, comido) ; période non terminée : hoy, esta semana, ya, todavía no, nunca.", "Pretérito indefinido : période terminée : ayer, el año pasado.", "Participes irréguliers : hecho, dicho, visto, escrito, puesto, vuelto, abierto."], examples: ["Este año he leído tres novelas.", "El año pasado leí cinco."], pitfalls: ["Accorder le participe passé avec haber : he leída.", "Séparer haber du participe."], remember: ["hoy, esta semana → perfecto.", "ayer, el año pasado → indefinido."] },
  "es:indef-imperf": { title: "le passé simple et l'imparfait dans le récit", rules: ["Indefinido : actions de premier plan, ponctuelles, qui font avancer le récit.", "Imperfecto : arrière-plan, description, habitudes, circonstances.", "Une action en cours (imparfait) est interrompue par une action ponctuelle (indefinido)."], examples: ["Llovía cuando llegamos a Toledo.", "Mientras mi abuelo trabajaba, estalló la guerra."], pitfalls: ["Raconter tout le récit à l'imparfait.", "Décrire un décor à l'indefinido."], remember: ["Premier plan : indefinido ; arrière-plan : imperfecto.", "Llovía cuando llegamos."] },
  "es:subjuntivo": { title: "le subjonctif présent", rules: ["Formation : radical de la 1re personne du présent + terminaisons inversées : hablar → hable ; comer → coma ; tener (tengo) → tenga ; hacer (hago) → haga.", "Irréguliers : ser → sea, ir → vaya, estar → esté, haber → haya, saber → sepa, dar → dé.", "Emplois : souhait, ordre négatif, but (para que), cuando + futur, expressions comme es importante que, ojalá."], examples: ["Es importante que todos reciclemos.", "Ojalá que llueva pronto."], pitfalls: ["Employer l'indicatif après para que ou ojalá.", "Oublier l'irrégularité de la 1re personne (tenga, pas tena)."], remember: ["hablar → hable ; comer → coma.", "para que, ojalá, es importante que + subjonctif."] },
  "es:imperativo": { title: "l'impératif", rules: ["Tú (affirmatif) : 3e personne du présent : habla, come, escribe ; irréguliers : ten, haz, pon, sal, ven, di, ve, sé.", "Usted / ustedes et toutes les formes négatives : subjonctif (hable, no hables, no comáis).", "Pronoms collés à l'impératif affirmatif : dímelo, levántate."], examples: ["Escribe un poema y léelo en voz alta.", "No uses el móvil en clase."], pitfalls: ["Employer l'impératif affirmatif à la forme négative : no habla.", "Oublier l'accent quand on ajoute un pronom : levántate."], remember: ["Négatif = no + subjonctif.", "ten, haz, pon, sal, ven, di, ve, sé."] },
  "es:subj-opinion": { title: "le subjonctif après les verbes d'opinion", rules: ["Opinion affirmative : creo que, pienso que + indicatif.", "Opinion négative : no creo que, no pienso que + subjonctif.", "Sentiments et jugements : me alegra que, es increíble que + subjonctif."], examples: ["Creo que la diversidad es una riqueza.", "No creo que sea tan fácil."], pitfalls: ["Mettre le subjonctif après creo que.", "Oublier le subjonctif après no creo que."], remember: ["creo que + indicatif.", "no creo que + subjonctif."] },
  "es:aunque": { title: "la concession : aunque", rules: ["aunque + indicatif : fait réel reconnu (même si c'est vrai).", "aunque + subjonctif : hypothèse ou fait que l'on ne prend pas en compte (même si).", "Autres connecteurs : sin embargo (cependant), a pesar de (malgré)."], examples: ["Aunque llueve, salimos.", "Aunque llueva mañana, saldremos."], pitfalls: ["Croire qu'aunque impose toujours le subjonctif.", "Confondre sin embargo et sino."], remember: ["aunque + indicatif : fait réel.", "aunque + subjonctif : hypothèse."] },
  "es:condicional": { title: "le conditionnel", rules: ["Infinitif + -ía, -ías, -ía, -íamos, -íais, -ían : hablaría, comería.", "Mêmes irréguliers qu'au futur : tendría, haría, diría, podría, saldría, vendría.", "Emplois : politesse, conseil, hypothèse (si + subjonctif imparfait → conditionnel)."], examples: ["Me gustaría visitar el museo del Prado.", "Deberías leer este libro."], pitfalls: ["Confondre conditionnel (hablaría) et imparfait (hablaba).", "Oublier l'accent."], remember: ["Infinitif + -ía.", "tendría, haría, diría."] },
  "es:si-subj": { title: "si + imparfait du subjonctif", rules: ["Hypothèse irréelle : si + subjonctif imparfait, conditionnel (Si tuviera dinero, viajaría).", "Formation : 3e personne du pluriel de l'indefinido sans -ron + -ra ou -se : tuvieron → tuviera / tuviese ; fueron → fuera.", "Jamais de conditionnel après si."], examples: ["Si la ciencia lo permitiera, curaríamos todas las enfermedades.", "Si fuera ministro, cambiaría las leyes."], pitfalls: ["Mettre le conditionnel après si.", "Mal former le subjonctif imparfait (tenera)."], remember: ["si + -ra / -se → conditionnel.", "tuvieron → tuviera."] },
  "es:para-que": { title: "le but : para que + subjonctif", rules: ["para + infinitif si le sujet est le même (Estudio para aprender).", "para que + subjonctif si les sujets sont différents (Te explico para que entiendas).", "Après un verbe au passé, para que + subjonctif imparfait."], examples: ["Plantamos árboles para que los pájaros vuelvan.", "Reciclamos para proteger el planeta."], pitfalls: ["Employer l'indicatif après para que.", "Employer para que quand le sujet est le même."], remember: ["Même sujet : para + infinitif.", "Sujets différents : para que + subjonctif."] },
  "es:quizas": { title: "nuancer : quizás, puede que", rules: ["quizás / tal vez + indicatif (plus sûr) ou subjonctif (moins sûr).", "puede que + subjonctif ; a lo mejor + indicatif.", "es posible / es probable que + subjonctif."], examples: ["Quizás los espacios públicos sean más verdes en el futuro.", "A lo mejor llega tarde."], pitfalls: ["Employer le subjonctif après a lo mejor.", "Employer l'indicatif après puede que."], remember: ["puede que + subjonctif.", "a lo mejor + indicatif."] },
  "es:pasiva": { title: "le passif et le se impersonnel", rules: ["Passif : ser + participe accordé + por (El puente fue construido por los romanos).", "Passif réfléchi : se + verbe à la 3e personne accordé avec le sujet (Se venden pisos).", "Se impersonnel : se + verbe au singulier (Se vive bien aquí)."], examples: ["La memoria de la guerra se transmite en las familias.", "Las calles fueron renombradas."], pitfalls: ["Oublier d'accorder le participe au passif.", "Mettre le verbe au singulier avec un sujet pluriel : se vende pisos."], remember: ["ser + participe accordé + por.", "se venden + pluriel."] },
  "es:relieve": { title: "la mise en relief", rules: ["Ser + élément mis en valeur + relatif accordé : Fue Cervantes quien escribió el Quijote ; Es aquí donde nací.", "Lo que + verbe + ser : Lo que me gusta es el final."], examples: ["Es en esta película donde el director critica la sociedad.", "Lo que importa es la verdad."], pitfalls: ["Utiliser que pour une personne au lieu de quien.", "Oublier d'accorder ser au temps du récit."], remember: ["Es … quien / donde / cuando.", "Lo que … es …"] },
  "es:concordancia": { title: "la concordance des temps", rules: ["Principale au présent ou au futur → subordonnée au subjonctif présent (Quiero que vengas).", "Principale au passé ou au conditionnel → subjonctif imparfait (Quería que vinieras).", "Discours indirect au passé : futur → conditionnel (Dijo que vendría)."], examples: ["El periodista pidió que no publicaran las fotos.", "Dijo que llegaría tarde."], pitfalls: ["Garder le subjonctif présent après un verbe au passé.", "Oublier de transformer le futur en conditionnel."], remember: ["Passé → subjonctif imparfait.", "Futur → conditionnel au discours indirect."] },
  "es:subj-imperfecto": { title: "le subjonctif imparfait", rules: ["Formation : 3e personne du pluriel de l'indefinido sans -ron + -ra (ou -se) : hablaron → hablara ; pudieron → pudiera ; dijeron → dijera.", "Emplois : après un verbe au passé (concordance), après si pour une hypothèse irréelle, après como si (comme si)."], examples: ["Me gustaría que las redes sociales fueran más seguras.", "Habla como si lo supiera todo."], pitfalls: ["Former à partir de l'infinitif (hablera).", "Employer le conditionnel après como si."], remember: ["-ron → -ra / -se.", "como si + subjonctif imparfait."] },

  /* ——— Allemand ——— */
  "de:komparativ": { title: "les adjectifs attributs et le comparatif", rules: ["L'adjectif attribut est invariable : Das Haus ist groß ; Die Häuser sind groß.", "Comparatif : adjectif + -er + als (kleiner als) ; souvent avec inflexion pour les adjectifs courts : alt → älter, groß → größer, jung → jünger.", "Irréguliers : gut → besser, viel → mehr, gern → lieber ; égalité : so … wie."], examples: ["Mein Bruder ist älter als ich.", "Berlin ist größer als München."], pitfalls: ["Employer mehr devant un adjectif (mehr groß).", "Utiliser wie au lieu de als au comparatif de supériorité."], remember: ["-er + als.", "gut → besser."] },
  "de:modalverben": { title: "les verbes de modalité", rules: ["können (pouvoir, savoir), müssen (devoir), dürfen (avoir le droit), wollen (vouloir), sollen (devoir, selon un autre), mögen / möchten (aimer, voudrais).", "Singulier irrégulier, sans terminaison aux 1re et 3e personnes : ich kann, er kann ; ich muss ; ich darf ; ich will.", "L'infinitif se place à la fin de la proposition : Ich muss heute lernen."], examples: ["In der Schule darf man nicht rauchen.", "Kannst du schwimmen?"], pitfalls: ["Ajouter -t : er kannt.", "Placer l'infinitif juste après le modal."], remember: ["ich kann / er kann.", "Infinitif en fin de phrase."] },
  "de:perfekt": { title: "le parfait", rules: ["haben ou sein au présent + participe II en fin de phrase.", "Verbes faibles : participe en ge…t (gespielt, gemacht) ; verbes forts : participe en ge…en, au radical souvent modifié (gegangen, gesehen).", "sein avec les verbes de déplacement et de changement d'état (gehen, fahren, kommen, werden)."], examples: ["Ich habe Fußball gespielt.", "Wir sind nach Berlin gefahren."], pitfalls: ["Employer haben avec un verbe de déplacement.", "Oublier de rejeter le participe à la fin."], remember: ["haben / sein + participe II à la fin.", "Déplacement : sein."] },
  "de:perfekt-stark": { title: "le parfait des verbes forts", rules: ["Participe II des verbes forts, en ge…en avec un radical parfois changé : gehen → gegangen, sehen → gesehen, schreiben → geschrieben, finden → gefunden, sprechen → gesprochen, fahren → gefahren.", "Verbes à particule séparable : ankommen → angekommen ; inséparables (be-, ver-, er-) sans ge- : verstanden, bekommen."], examples: ["Ich habe ein Buch geschrieben.", "Sie ist spät angekommen."], pitfalls: ["Écrire « gegeht ».", "Ajouter ge- à un verbe inséparable (geverstanden)."], remember: ["Fort : ge-…-en.", "Inséparable : pas de ge-."] },
  "de:werden": { title: "le futur avec werden", rules: ["werden (ich werde, du wirst, er wird, wir werden, ihr werdet, sie werden) + infinitif en fin de phrase.", "Souvent, l'allemand emploie le présent avec un complément de temps (Morgen fahre ich nach Wien)."], examples: ["Nächstes Jahr werde ich Spanisch lernen.", "Wir werden das Museum besuchen."], pitfalls: ["Confondre werden + infinitif (futur) et werden + participe II (passif).", "Oublier le changement de voyelle : du wirst."], remember: ["werden + infinitif à la fin.", "du wirst, er wird."] },
  "de:dativ": { title: "le datif", rules: ["Articles au datif : dem (masculin et neutre), der (féminin), den + -n (pluriel).", "Prépositions toujours suivies du datif : aus, bei, mit, nach, seit, von, zu.", "Verbes avec un complément au datif : helfen, danken, gehören, gefallen."], examples: ["Ich fahre mit dem Zug zu meiner Oma.", "Das Geschenk gefällt dem Kind."], pitfalls: ["Employer l'accusatif après mit.", "Oublier le -n au datif pluriel (den Kindern)."], remember: ["aus, bei, mit, nach, seit, von, zu + datif.", "dem, der, dem, den …n."] },
  "de:dass-weil": { title: "les subordonnées en dass et weil", rules: ["Dans une subordonnée, le verbe conjugué se place en dernière position : …, weil ich müde bin.", "dass : complétive (Ich glaube, dass er kommt) ; weil : cause.", "Une virgule sépare toujours la principale de la subordonnée."], examples: ["Ich lerne Deutsch, weil ich nach Berlin reisen will.", "Er sagt, dass die Medien wichtig sind."], pitfalls: ["Laisser le verbe en deuxième position après weil.", "Oublier la virgule."], remember: ["Subordonnée : verbe conjugué à la fin.", "Virgule avant dass et weil."] },
  "de:praeteritum": { title: "le prétérit", rules: ["Verbes faibles : radical + -te (ich spielte, wir spielten).", "Verbes forts : changement de voyelle, sans terminaison aux 1re et 3e personnes du singulier : gehen → ging, kommen → kam, sehen → sah, finden → fand.", "sein → war, haben → hatte, werden → wurde ; temps du récit écrit."], examples: ["Früher spielten die Kinder auf der Straße.", "Er kam spät nach Hause."], pitfalls: ["Ajouter -te à un verbe fort (gehte).", "Utiliser le prétérit pour tous les verbes à l'oral (on préfère le parfait, sauf sein, haben et les modaux)."], remember: ["Faible : -te ; fort : voyelle changée.", "war, hatte."] },
  "de:relativ": { title: "les propositions relatives", rules: ["Le pronom relatif reprend le genre et le nombre de l'antécédent, et prend le cas de sa fonction dans la relative : der, die, das ; den (accusatif masculin) ; dem, der, dem, denen (datif) ; dessen, deren (génitif).", "Le verbe conjugué se place à la fin de la relative.", "La relative est encadrée de virgules."], examples: ["Das ist der Mann, der hier wohnt.", "Die Freunde, mit denen ich reise, kommen aus Wien."], pitfalls: ["Choisir le cas d'après la principale au lieu de la relative.", "Oublier de rejeter le verbe à la fin."], remember: ["Genre et nombre : antécédent ; cas : fonction dans la relative.", "Verbe à la fin."] },
  "de:zu-infinitiv": { title: "la proposition infinitive avec zu", rules: ["zu + infinitif à la fin du groupe : Es ist wichtig, die Umwelt zu schützen.", "Verbes à particule séparable : zu entre la particule et le verbe (anzurufen, aufzuräumen).", "Après les modaux, pas de zu (Ich muss lernen)."], examples: ["Wir versuchen, weniger Plastik zu benutzen.", "Ich habe vergessen, dich anzurufen."], pitfalls: ["Mettre zu après un modal.", "Écrire « zu anrufen »."], remember: ["…, etwas zu tun.", "anzurufen."] },
  "de:passiv": { title: "le passif", rules: ["werden (conjugué) + participe II en fin de phrase : Das Haus wird gebaut.", "Prétérit : wurde gebaut ; parfait : ist gebaut worden.", "Complément d'agent : von + datif ; substituts du passif : man, sich lassen + infinitif."], examples: ["Das Bild wurde 1937 gemalt.", "Hier wird Deutsch gesprochen."], pitfalls: ["Utiliser sein au lieu de werden pour le passif d'action.", "Oublier worden au parfait passif."], remember: ["werden + participe II.", "von + datif."] },
  "de:konj1": { title: "le discours indirect au subjonctif I", rules: ["Subjonctif I : radical de l'infinitif + -e (er komme, er habe) ; sein : er sei.", "Le discours indirect dans la presse emploie le subjonctif I pour rapporter des propos sans les prendre en charge.", "Si le subjonctif I est identique à l'indicatif, on emploie le subjonctif II (sie hätten)."], examples: ["Der Minister sagte, er sei zufrieden.", "Sie erklärte, sie habe keine Zeit."], pitfalls: ["Confondre er sei (subjonctif) et er ist (indicatif).", "Oublier de changer les pronoms."], remember: ["er sei, er habe, er komme.", "Discours rapporté dans la presse."] },
  "de:obwohl": { title: "la concession : obwohl", rules: ["obwohl introduit une subordonnée : le verbe conjugué est à la fin (…, obwohl es regnet).", "trotzdem est un adverbe : il entraîne l'inversion (Es regnet, trotzdem gehen wir spazieren).", "trotz + génitif : malgré."], examples: ["Obwohl er müde ist, arbeitet er weiter.", "Trotz des Regens spielen wir."], pitfalls: ["Laisser le verbe en deuxième position après obwohl.", "Oublier l'inversion après trotzdem."], remember: ["obwohl : verbe à la fin.", "trotzdem : inversion."] },
  "de:konj2": { title: "le subjonctif II et l'hypothèse", rules: ["würde + infinitif pour la plupart des verbes (ich würde reisen).", "Formes propres : wäre (sein), hätte (haben), könnte, müsste, dürfte.", "Hypothèse : Wenn ich Zeit hätte, würde ich reisen ; souhait : Ich hätte gern…"], examples: ["Wenn ich Künstler wäre, würde ich die Macht kritisieren.", "Könntest du mir helfen?"], pitfalls: ["Mettre würde dans la subordonnée avec wenn devant sein ou haben (wenn ich sein würde).", "Oublier le verbe à la fin dans la subordonnée."], remember: ["wäre, hätte, würde + infinitif.", "Wenn …, würde …"] },
  "de:damit-umzu": { title: "le but : damit, um … zu", rules: ["um … zu + infinitif quand le sujet est le même (Ich spare, um ein Fahrrad zu kaufen).", "damit + subordonnée quand les sujets sont différents (Ich erkläre es, damit du es verstehst).", "Le verbe conjugué est à la fin après damit."], examples: ["Wir pflanzen Bäume, um das Klima zu schützen.", "Wir recyceln, damit die Natur sauber bleibt."], pitfalls: ["Employer damit avec le même sujet.", "Oublier zu."], remember: ["Même sujet : um … zu.", "Sujets différents : damit."] },
  "de:nuancieren": { title: "nuancer : vielleicht, wohl", rules: ["vielleicht (peut-être), wahrscheinlich (probablement), sicher (sûrement), wohl (sans doute, supposition).", "Ces adverbes se placent généralement après le verbe conjugué.", "Modaux de supposition : Das könnte stimmen ; Er dürfte recht haben."], examples: ["Der öffentliche Raum wird wohl digitaler.", "Vielleicht hat sie recht."], pitfalls: ["Placer l'adverbe avant le verbe sans inversion (Vielleicht sie hat recht).", "Confondre wohl (supposition) et wohl (bien) selon le contexte."], remember: ["Adverbe en tête : inversion.", "wohl : supposition."] },
  "de:passiv-ersatz": { title: "le passif et ses substituts", rules: ["Passif : werden + participe II ; état : sein + participe II (Die Tür ist geschlossen).", "Substituts : man + verbe actif (Man erinnert sich an…), sich lassen + infinitif (Das lässt sich erklären), sein + zu + infinitif (Das ist zu beachten)."], examples: ["Das Denkmal wurde 1990 errichtet.", "Die Geschichte lässt sich nicht vergessen."], pitfalls: ["Confondre passif d'action (wird geschlossen) et d'état (ist geschlossen).", "Oublier sich dans sich lassen."], remember: ["werden : action ; sein : état.", "man, sich lassen, sein zu."] },
  "de:partizip": { title: "les participes adjectivés", rules: ["Participe I (infinitif + -d) : action en cours, sens actif : das lachende Kind.", "Participe II : action accomplie, sens passif : das gelesene Buch.", "Employés comme épithètes, ils prennent les terminaisons des adjectifs."], examples: ["Die wachsende Zahl der Nutzer…", "Die veröffentlichten Daten sind falsch."], pitfalls: ["Oublier la terminaison de l'adjectif.", "Confondre participe I (actif) et II (passif)."], remember: ["Participe I : -end- ; participe II : ge-…-t/-en.", "Terminaisons d'adjectif épithète."] },
  "de:konj1-2": { title: "le subjonctif I et le subjonctif II", rules: ["Subjonctif I : discours rapporté (er sagt, er sei krank).", "Subjonctif II : irréel, politesse, souhait (er wäre, er hätte, er würde kommen).", "Si le subjonctif I se confond avec l'indicatif, on emploie le subjonctif II."], examples: ["Die Zeitung schreibt, der Bericht sei falsch.", "Wenn die Information stimmen würde, wäre das ein Skandal."], pitfalls: ["Utiliser le subjonctif II pour rapporter des propos neutres alors que le I est disponible.", "Confondre sei et wäre."], remember: ["I : rapporter ; II : imaginer.", "sei / wäre."] },
};

