const LANG_NAME: Record<string, string> = { anglais: "anglais", espagnol: "espagnol", allemand: "allemand", llcer: "anglais" };
const COL: Record<string, number> = { anglais: 1, llcer: 1, espagnol: 2, allemand: 3 };

function languageLesson(unitId: string): Lesson {
  const unit = findUnit(unitId)!;
  const axis = unitId.split("-").slice(2).join("-");
  const g = G[UNIT_GRAMMAR[unitId]!]!;
  const level = unit.notions.find((n) => n.startsWith("Niveau visé"));
  const themes = AXIS_THEMES[axis] ?? [];
  const vocab = themes.flatMap((th) => LEXIQUE[th].slice(0, 6)).slice(0, 8).map((row) => `${row[COL[unit.subject]!]} : ${row[0]}`);
  const culture = axis === "axe6" ? AXE6[unit.subject === "llcer" ? "anglais" : unit.subject] ?? [] : [];
  return lesson(
    unitId,
    `${AXIS[axis] ?? unit.title} En ${LANG_NAME[unit.subject]}, ce chapitre travaille ${g.title}${level ? ` (${level.toLowerCase().replace("niveau visé : ", "niveau visé ")})` : ""}.`,
    [[`Grammaire : ${g.title}`, g.rules], ["Exemples", g.examples], ...(vocab.length ? [["Vocabulaire du thème", vocab] as [string, string[]]] : []), ...(culture.length ? [["Repères culturels", culture] as [string, string[]]] : [])],
    g.pitfalls,
    g.remember,
  );
}

const LANGUAGE_UNITS = UNITS.filter((u) => ["anglais", "espagnol", "allemand", "llcer"].includes(u.subject)).map((u) => u.id);

export const LANGUES_LESSONS: LessonSet = {
  id: "cours-langues-vivantes",
  subject: "anglais",
  status: "needs_review",
  sources: [SRC.lv, SRC.c4],
  lessons: LANGUAGE_UNITS.map(languageLesson),
};

